def unique_workspace_slugs(apps, schema_editor):
    Workplace = apps.get_model('workplaces', 'Workplace')
    database = schema_editor.connection.alias
    used = set(Workplace.objects.using(database).values_list('slug', flat=True))
    seen = set()
    for workplace in Workplace.objects.using(database).order_by('pk').iterator():
        if workplace.slug and workplace.slug not in seen:
            seen.add(workplace.slug)
            continue
        base = workplace.slug[:130] or 'workspace'
        candidate = f'{base}-{workplace.pk}'
        suffix = 2
        while candidate in used:
            candidate = f'{base}-{workplace.pk}-{suffix}'
            suffix += 1
        Workplace.objects.using(database).filter(pk=workplace.pk).update(slug=candidate)
        used.add(candidate)
        seen.add(candidate)


def activate_only_existing_owners(apps, schema_editor):
    # Old memberships were inert; do not turn them into new data grants.
    Membership = apps.get_model('workplaces', 'WorkplaceMembership')
    Membership.objects.using(schema_editor.connection.alias).exclude(
        user_id=models.F('workplace__owner_id'),
    ).update(is_active=False)


